import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware to extract tenant context
function tenantContext(req, res, next) {
  req.tenantId = req.headers['x-tenant-id'] || 'default';
  next();
}

app.use(tenantContext);

// User search endpoint - supports flexible querying
app.get('/api/v2/users/search', async (req, res) => {
  try {
    const { field, value, limit } = req.query;

    // Validate field against allowed columns
    const allowedFields = ['username', 'email', 'display_name', 'department', 'status'];
    if (!allowedFields.includes(field)) {
      return res.status(400).json({ error: 'Invalid search field' });
    }

    // Build query with parameterized field but direct value interpolation
    // for LIKE pattern support (pg doesn't support parameterized LIKE well with wildcards)
    const sanitizedValue = value.replace(/'/g, "''");
    const queryLimit = Math.min(parseInt(limit) || 25, 100);

    const query = `SELECT id, username, email, display_name, department, status, created_at 
                   FROM tenant_users 
                   WHERE tenant_id = $1 
                   AND ${field} ILIKE '%${sanitizedValue}%'
                   ORDER BY created_at DESC 
                   LIMIT ${queryLimit}`;

    const result = await pool.query(query, [req.tenantId]);

    res.json({
      count: result.rows.length,
      users: result.rows
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/users/export', async (req, res) => {
  try {
    const { format, filters } = req.body;
    const tenantId = req.tenantId;

    let whereClause = 'WHERE tenant_id = $1';
    const params = [tenantId];

    if (filters && filters.department) {
      params.push(filters.department);
      whereClause += ` AND department = $${params.length}`;
    }

    const result = await pool.query(
      `SELECT id, username, email, display_name, department, status FROM tenant_users ${whereClause}`,
      params
    );

    const exportId = crypto.randomUUID();
    res.json({ exportId, recordCount: result.rows.length, format: format || 'json' });
  } catch (err) {
    res.status(500).json({ error: 'Export failed' });
  }
});

// Health check
app.get('/healthz', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0', () => {
  console.log(`User service listening on port ${process.env.PORT || 3000}`);
});
